@Bean
public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
    http.authorizeHttpRequests(authz -> authz
            .anyRequest().authenticated()
        )
        .formLogin()
            .loginPage("/login") // optional custom login page
            .permitAll()
        .and()
        .logout()
            .logoutSuccessUrl("/")
            .permitAll();
    return http.build();
}

